// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatIllegalArgumentException;

import java.util.Random;
import java.util.TreeSet;

import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Test;

class LmdbInlineIncomingIndexTest {

	private final LmdbAdjacencyArena arena = new LmdbAdjacencyArena(4 << 20);

	@AfterEach
	void close() {
		arena.close();
	}

	private static long key(int radixPrefix, long low) {
		return ((long) radixPrefix << 48) | low;
	}

	@Test
	void emptyPlaneAllocatesNothing() {
		long before = arena.allocatedBytes();
		LmdbInlineIncomingIndex index = LmdbInlineIncomingIndex.build(arena, new long[0], new long[0]);

		assertThat(index).isNull();
		assertThat(arena.allocatedBytes()).isEqualTo(before);
	}

	@Test
	void radixPrefixBoundariesResolve() {
		// prefixes 0, 1, 32768, 65535 with a few keys each
		long[] keys = {
				key(0, 1), key(0, 500),
				key(1, 0), key(1, 77),
				key(32_768, 1234),
				key(65_535, 0), key(65_535, 0xFFFF_FFFF_FFFFL)
		};
		long[] refs = { 11, 12, 21, 22, 31, 41, 42 };
		LmdbInlineIncomingIndex index = LmdbInlineIncomingIndex.build(arena, keys, refs);

		assertThat(index.keyCount()).isEqualTo(7);
		// a new block starts at every prefix change
		assertThat(index.blockCount()).isEqualTo(4);
		for (int i = 0; i < keys.length; i++) {
			assertThat(index.findRun(keys[i])).as("key %d", i).isEqualTo(refs[i]);
		}
		// missing keys in present and absent prefixes
		assertThat(index.findRun(key(0, 2))).isEqualTo(-1);
		assertThat(index.findRun(key(1, 78))).isEqualTo(-1);
		assertThat(index.findRun(key(2, 0))).isEqualTo(-1);
		assertThat(index.findRun(key(40_000, 5))).isEqualTo(-1);
	}

	@Test
	void unsignedBoundaryKeysResolve() {
		long[] keys = { 0, 1, Long.MAX_VALUE, Long.MIN_VALUE, -2L, -1L };
		long[] refs = { 1, 2, 3, 4, 5, 6 };
		// unsigned ascending order: 0, 1, 0x7fff.., 0x8000.., 0xffff..fe, 0xffff..ff
		LmdbInlineIncomingIndex index = LmdbInlineIncomingIndex.build(arena, keys, refs);

		for (int i = 0; i < keys.length; i++) {
			assertThat(index.findRun(keys[i])).isEqualTo(refs[i]);
		}
		assertThat(index.findRun(2)).isEqualTo(-1);
		assertThat(index.findRun(-3L)).isEqualTo(-1);
	}

	@Test
	void multipleBlocksWithinOnePrefixSplitAt256Keys() {
		int count = 700; // three blocks in one prefix
		long[] keys = new long[count];
		long[] refs = new long[count];
		for (int i = 0; i < count; i++) {
			keys[i] = key(7, 10L + i * 3);
			refs[i] = 1000 + i;
		}
		LmdbInlineIncomingIndex index = LmdbInlineIncomingIndex.build(arena, keys, refs);

		assertThat(index.blockCount()).isEqualTo(3);
		for (int i = 0; i < count; i += 41) {
			assertThat(index.findRun(keys[i])).isEqualTo(refs[i]);
		}
		assertThat(index.findRun(key(7, 11))).isEqualTo(-1);
		assertThat(index.findRun(key(7, 10L + count * 3))).isEqualTo(-1);
	}

	@Test
	void explicitAndInferredPlanesNeverAlias() {
		long[] keys = { key(3, 1), key(3, 2) };
		LmdbInlineIncomingIndex explicitIndex = LmdbInlineIncomingIndex.build(arena, keys, new long[] { 100, 101 });
		LmdbInlineIncomingIndex inferredIndex = LmdbInlineIncomingIndex.build(arena, new long[] { key(3, 2) },
				new long[] { 200 });

		assertThat(explicitIndex.findRun(key(3, 1))).isEqualTo(100);
		assertThat(explicitIndex.findRun(key(3, 2))).isEqualTo(101);
		assertThat(inferredIndex.findRun(key(3, 1))).isEqualTo(-1);
		assertThat(inferredIndex.findRun(key(3, 2))).isEqualTo(200);
	}

	@Test
	void invalidInputsAreRejected() {
		assertThatIllegalArgumentException().isThrownBy(
				() -> LmdbInlineIncomingIndex.build(arena, new long[] { 5, 5 }, new long[] { 1, 2 }));
		assertThatIllegalArgumentException().isThrownBy(
				() -> LmdbInlineIncomingIndex.build(arena, new long[] { 5, 4 }, new long[] { 1, 2 }));
		assertThatIllegalArgumentException().isThrownBy(
				() -> LmdbInlineIncomingIndex.build(arena, new long[] { 5 }, new long[] { 1, 2 }));
	}

	@Test
	void randomizedKeysAlwaysVerifyTheCompleteKey() {
		Random random = new Random(42);
		TreeSet<Long> keySet = new TreeSet<>(Long::compareUnsigned);
		while (keySet.size() < 5000) {
			keySet.add(random.nextLong());
		}
		long[] keys = keySet.stream().mapToLong(Long::longValue).toArray();
		long[] refs = new long[keys.length];
		for (int i = 0; i < keys.length; i++) {
			refs[i] = i + 1;
		}
		LmdbInlineIncomingIndex index = LmdbInlineIncomingIndex.build(arena, keys, refs);

		for (int i = 0; i < keys.length; i += 7) {
			assertThat(index.findRun(keys[i])).isEqualTo(refs[i]);
		}
		for (int i = 0; i < 2000; i++) {
			long probe = random.nextLong();
			if (!keySet.contains(probe)) {
				assertThat(index.findRun(probe)).isEqualTo(-1);
			}
		}
	}
}
